import { createScreenshotSVG } from "@flourish/pocket-knife";
import { select } from "d3-selection";
import {
	appendTo,
	format,
	getContainer,
	visible,
	autoTitle,
	_updateTitle,
	small_gap,
} from "../common.js";
import { remToPx, roundDown } from "../utils.js";

var legend_count = 0;
var DEFAULTS = Object.freeze({
	show_legend: true,

	title_mode: "auto",
	title: "",

	clip_height: 1,
	small_symbol_size: 0.5,

	shape_fill: "#eeeeee",
	shape_stroke: "#555555",
});

function ContinuousSizeLegend(state_) {
	this._state = state_;
	for (var key in DEFAULTS) {
		if (this._state[key] === undefined) this._state[key] = DEFAULTS[key];
	}

	this._scaleFunction = undefined;
	this._formatFunction = undefined;
	this._id = "fl-legend-continuous-size-" + legend_count;
	this._visible = true;
	this._auto_title = "";
	this._symbol_type = "circle";
	this._spike_width = 10;

	this._container = select(document.createElement("div"))
		.attr("class", "fl-legend-container")
		.attr("id", this._id)
		.style("display", "none")
		.style("align-items", "center");

	this._container.append("p").attr("class", "fl-legend-title");

	this._container.append("div").classed("min label", true);

	var symbols_container = this._container
		.append("div")
		.classed("symbols", true);

	symbols_container
		.append("canvas")
		.classed("min symbol", true)
		.attr("width", 0)
		.attr("height", 0);

	symbols_container
		.append("canvas")
		.classed("max symbol", true)
		.attr("width", 0)
		.attr("height", 0);

	this._container.append("div").classed("max label", true);

	legend_count++;

	return this;
}

// Common methods
ContinuousSizeLegend.prototype.appendTo = appendTo;
ContinuousSizeLegend.prototype.format = format;
ContinuousSizeLegend.prototype.autoTitle = autoTitle;
ContinuousSizeLegend.prototype._updateTitle = _updateTitle;
ContinuousSizeLegend.prototype.getContainer = getContainer;
ContinuousSizeLegend.prototype.visible = visible;

ContinuousSizeLegend.prototype.scale = function (scaleFunction_) {
	// domain and range are assumed to be [0, max] where max is a number > 0
	if (scaleFunction_ === undefined) return this._scaleFunction;
	this._scaleFunction = scaleFunction_;
	return this;
};

ContinuousSizeLegend.prototype.symbolType = function (symbol_type_) {
	if (symbol_type_ === undefined) return this._symbol_type;
	this._symbol_type = symbol_type_;
	return this;
};

ContinuousSizeLegend.prototype.spikeWidth = function (spike_width_) {
	if (spike_width_ === undefined) return this._spike_width;
	this._spike_width = spike_width_;
	return this;
};

ContinuousSizeLegend.prototype.update = function () {
	var should_display = this._state.show_legend && this._visible;

	var h = Math.ceil(remToPx(this._state.clip_height));
	this._container
		.style("display", should_display ? "inline-flex" : "none")
		.style(
			"align-items",
			this._symbol_type === "circle" ? "center" : "baseline",
		)
		.style("min-height", h + "px");

	if (!should_display || !this._scaleFunction) return this;

	if (this._scaleFunction.domain()[0] !== 0) {
		console.warn("Non zero domain[0] in ContinuousSizeLegend");
	}

	if (this._scaleFunction.range()[0] !== 0) {
		console.warn("Non zero range[0] in ContinuousSizeLegend");
	}

	this._updateTitle();
	this._updateLegend();

	return this;
};

ContinuousSizeLegend.prototype._updateSymbolCanvas = function (
	el,
	w,
	h,
	px_ratio,
) {
	var canvas = this._container
		.select(el)
		.style("width", w + "px")
		.style("height", h + "px")
		.attr("width", w * px_ratio)
		.attr("height", h * px_ratio);

	var ctx = canvas.node().getContext("2d");
	ctx.scale(px_ratio, px_ratio);
	ctx.clearRect(0, 0, w, h);

	return ctx;
};

ContinuousSizeLegend.prototype._updateCircle = function (
	el,
	val,
	h,
	px_ratio,
	fill,
	stroke,
) {
	var r = this._scaleFunction(val);
	var w = Math.ceil(2 * r);
	var ctx = this._updateSymbolCanvas(el, w, h, px_ratio);

	// To ensure size of circle is accurate, draw two circles where the outer (darker) one is the
	// required size and the inside one slightly smaller. This gives the impression of a circle with
	// darker stroke
	ctx.beginPath();
	ctx.fillStyle = stroke;
	ctx.arc(0.5 * w, 0.5 * h, r, 0, 2 * Math.PI);
	ctx.fill();

	ctx.beginPath();
	ctx.fillStyle = fill;
	ctx.arc(0.5 * w, 0.5 * h, Math.max(r - 1, 0), 0, 2 * Math.PI);
	ctx.fill();
};

ContinuousSizeLegend.prototype._updateSpike = function (
	el,
	val,
	h,
	px_ratio,
	fill,
	stroke,
) {
	var spike_h = this._scaleFunction(val);
	var w = Math.ceil(this._spike_width);
	var ctx = this._updateSymbolCanvas(el, w, h, px_ratio);

	// Some trigonometry to create a 1px stroke
	var half_top_angle = Math.atan((0.5 * w) / spike_h);
	var stroke_offset_x = 1 / Math.cos(half_top_angle);
	var stroke_offset_y = 1 / Math.sin(half_top_angle);

	// To ensure size of spike is accurate, draw two spikes where the outer (darker) one is the
	// required size and the inside one slightly smaller. This gives the impression of a spike with
	// darker stroke
	ctx.beginPath();
	ctx.fillStyle = stroke;
	ctx.moveTo(0, h);
	ctx.lineTo(0.5 * w, h - spike_h);
	ctx.lineTo(w, h);
	ctx.fill();

	ctx.beginPath();
	ctx.fillStyle = fill;
	ctx.moveTo(stroke_offset_x, h);
	ctx.lineTo(0.5 * w, h - spike_h + stroke_offset_y);
	ctx.lineTo(w - stroke_offset_x, h);
	ctx.fill();
};

ContinuousSizeLegend.prototype._updateLegend = function () {
	var domain = this._scaleFunction.domain();
	var range = this._scaleFunction.range();
	var format = this._formatFunction;

	var s = this._state;
	var fill = s.shape_fill;
	var stroke = s.shape_stroke;
	var pixel_ratio = window.devicePixelRatio || 1;

	var h = remToPx(s.clip_height);
	h = Math.ceil(Math.min(h, range[1] * 2));

	// Calculate max symbol size
	var symbol = this._symbol_type;
	var val_max_unrounded = this._scaleFunction.invert(
		symbol === "circle" ? h / 2 : h,
	);
	val_max_unrounded = Math.min(val_max_unrounded, domain[1]);
	var val_max = roundDown(val_max_unrounded) || 0;

	var val_min = val_max * s.small_symbol_size;

	this._container
		.select(".symbols")
		.style("display", "flex")
		.style("flex-wrap", "nowrap");

	this._container.select(".min.symbol").style("margin-right", "0.25rem");

	// Min label
	this._container
		.select(".min.label")
		.style("user-select", "none")
		.style("line-height", "1.25em")
		.text(function () {
			return format ? format(val_min) : val_min;
		})
		.style("padding-inline-start", 0)
		.style("padding-inline-end", small_gap);

	// Min symbol
	if (symbol === "circle") {
		this._updateCircle(".min.symbol", val_min, h, pixel_ratio, fill, stroke);
	} else if (symbol === "spike") {
		this._updateSpike(".min.symbol", val_min, h, pixel_ratio, fill, stroke);
	}

	// Max symbol
	if (symbol === "circle") {
		this._updateCircle(".max.symbol", val_max, h, pixel_ratio, fill, stroke);
	} else if (symbol === "spike") {
		this._updateSpike(".max.symbol", val_max, h, pixel_ratio, fill, stroke);
	}

	// Max label
	this._container
		.select(".max.label")
		.style("user-select", "none")
		.style("line-height", "1.25em")
		.text(function () {
			return format ? format(val_max) : val_max;
		})
		.style("padding-inline-start", small_gap)
		.style("padding-inline-end", 0);
};

ContinuousSizeLegend.prototype.prepareScreenshotSVG = function () {
	if (!this._state.show_legend || !this._visible) return;

	createScreenshotSVG(
		"#fl-layout-wrapper",
		this._id + "-svg-screenshot-container",
	)
		.addTextElements(".min.label")
		.addCircleElements(".min.symbol")
		.addCircleElements(".max.symbol")
		.addTextElements(".max.label");
};

ContinuousSizeLegend.prototype.clearScreenshotSVG = function () {
	const container = document.getElementById(
		this._id + "-svg-screenshot-container",
	);
	if (container) container.remove();
};

export default ContinuousSizeLegend;
